import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate, useParams } from "react-router-dom";
import {
  CheckCircle,
  AlertCircle,
  User,
  Globe,
  MapPin,
  School,
  Users,
  Heart,
  Map,
  Activity,
  Phone,
} from "lucide-react";
import Layout from "../Layout";

export default function EditCandidate() {
  const navigate = useNavigate();
  const { id } = useParams();
  const [formData, setFormData] = useState({
    CFF: "",
    First_Name: "",
    Last_Name: "",
    Gender: "",
    Nationality: "",
    Sector: "",
    Observation: "",
    Note: 0,
    hometown: "",
    phoneNumber: "",
    parentPhoneNumber: "",
    geographic_criteria: "",
    status: "candidate",
    criteria: [], // Array to store { criterionId, description }
  });
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [criteria, setCriteria] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  // Fetch candidate data and criteria on mount
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      const token = localStorage.getItem("token");
      if (!token) {
        setError("Authentication required. Please log in.");
        setIsLoading(false);
        return;
      }

      try {
        const [candidateResponse, criteriaResponse] = await Promise.all([
          axios.get(`${process.env.REACT_APP_API_URL}/api/candidates/${id}`, {
            headers: { Authorization: `Bearer ${token}` },
          }),
          axios.get(`${process.env.REACT_APP_API_URL}/api/criteria`, {
            headers: { Authorization: `Bearer ${token}` },
          }),
        ]);

        const candidateData = candidateResponse.data.data;
        const criteriaData = criteriaResponse.data;

        // Map existing criteria fields to the new criteria array format
        const criteriaMap = {
          "Critère scolaire": candidateData.school_criteria,
          "Critère familial": candidateData.family_criteria,
          "Critère social": candidateData.social_criteria,
          "Critère physique": candidateData.physical_criteria,
        };

        const mappedCriteria = criteriaData.map((criterion) => ({
          criterionId: criterion._id,
          description: criteriaMap[criterion.name] || "",
        }));

        setFormData({
          ...candidateData,
          criteria: mappedCriteria,
        });
        setCriteria(criteriaData);
      } catch (error) {
        const errorMsg = error.response?.data?.message || "Failed to fetch data.";
        setError(errorMsg);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, [id]);

  // Calculate Note dynamically
  useEffect(() => {
    const calculateNote = () => {
      let totalPoints = 0;

      formData.criteria.forEach((selectedCriterion) => {
        const criterion = criteria.find((c) => c._id === selectedCriterion.criterionId);
        if (criterion) {
          const selectedCase = criterion.cases.find(
            (c) => c.description === selectedCriterion.description
          );
          if (selectedCase) {
            totalPoints += selectedCase.points;
          }
        }
      });

      const geoPoints = parseInt(formData.geographic_criteria) || 0;
      totalPoints += geoPoints;

      setFormData((prev) => ({
        ...prev,
        Note: totalPoints,
      }));
    };

    if (!isLoading && criteria.length > 0) {
      calculateNote();
    }
  }, [formData.criteria, formData.geographic_criteria, criteria, isLoading]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleCriterionChange = (criterionId, description) => {
    setFormData((prev) => ({
      ...prev,
      criteria: prev.criteria.map((c) =>
        c.criterionId === criterionId ? { ...c, description } : c
      ),
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setIsSubmitting(true);

    const token = localStorage.getItem("token");
    const role = localStorage.getItem("role");

    // Prepare data to send, excluding old criteria fields
    const submitData = {
      ...formData,
      school_criteria: undefined,
      family_criteria: undefined,
      social_criteria: undefined,
      physical_criteria: undefined,
    };

    try {
      const response = await axios.put(
        `${process.env.REACT_APP_API_URL}/api/candidates/${id}`,
        submitData,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: role,
          },
        }
      );

      if (response.data.success) {
        setSuccess("Candidat mis à jour avec succès !");
        const updatedStatus = response.data.data.status;
        setTimeout(() => {
          if (updatedStatus === "candidate") {
            navigate("/Candidates");
          } else if (updatedStatus === "selected") {
            navigate("/Selected");
          } else {
            navigate("/Candidates");
          }
        }, 2000);
      } else {
        setError("Échec de la mise à jour du candidat.");
      }
    } catch (err) {
      setError(err.response?.data?.message || "Une erreur s'est produite.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-screen">
        <svg
          className="animate-spin h-8 w-8 text-gray-500"
          xmlns="http://www.w3.org/2000/svg"
          fill="none"
          viewBox="0 0 24 24"
        >
          <circle
            className="opacity-25"
            cx="12"
            cy="12"
            r="10"
            stroke="currentColor"
            strokeWidth="4"
          />
          <path
            className="opacity-75"
            fill="currentColor"
            d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
          />
        </svg>
      </div>
    );
  }

  return (
    <Layout>
      <div className="max-w-5xl mx-auto">
        <div className="bg-white rounded-xl shadow-xl overflow-hidden">
          <div className="bg-primary text-primary-foreground p-6">
            <h2 className="text-2xl font-bold tracking-tight">Modifier un candidat</h2>
            <p className="text-primary-foreground/80 mt-1">Mettez à jour les détails du candidat</p>
          </div>

          {(error || success) && (
            <div
              className={`p-4 ${
                error ? "bg-red-50" : "bg-green-50"
              } border-l-4 ${
                error ? "border-red-500" : "border-green-500"
              } flex items-center gap-3`}
            >
              {error ? (
                <AlertCircle className="h-5 w-5 text-red-500" />
              ) : (
                <CheckCircle className="h-5 w-5 text-green-500" />
              )}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>
                {error || success}
              </p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="p-6">
            <div className="space-y-8">
              <div>
                <h3 className="text-lg font-medium text-gray-900 border-b pb-2">Informations personnelles</h3>
                <div className="mt-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">CFF</label>
                    <input
                      type="text"
                      name="CFF"
                      value={formData.CFF}
                      onChange={handleChange}
                      className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                      required
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Prénom</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="First_Name"
                        value={formData.First_Name}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      />
                      <User className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Nom de famille</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="Last_Name"
                        value={formData.Last_Name}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      />
                      <User className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Genre</label>
                    <select
                      name="Gender"
                      value={formData.Gender}
                      onChange={handleChange}
                      className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                      required
                    >
                      <option value="">Sélectionnez le genre</option>
                      <option value="Male">Homme</option>
                      <option value="Female">Femme</option>
                      <option value="Other">Autre</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Nationalité</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="Nationality"
                        value={formData.Nationality}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      />
                      <Globe className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Filière</label>
                    <input
                      type="text"
                      name="Sector"
                      value={formData.Sector}
                      onChange={handleChange}
                      className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                      required
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Numéro de téléphone</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="phoneNumber"
                        value={formData.phoneNumber}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                      />
                      <Phone className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Numéro de téléphone du parent</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="parentPhoneNumber"
                        value={formData.parentPhoneNumber}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                      />
                      <Phone className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2 md:col-span-2 lg:col-span-3">
                    <label className="block text-sm font-medium text-gray-700">Ville d'origine</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="hometown"
                        value={formData.hometown}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      />
                      <MapPin className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                </div>
              </div>

              <div>
                <h3 className="text-lg font-medium text-gray-900 border-b pb-2">Critères d'évaluation</h3>
                <div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-6">
                  {criteria.map((criterion) => (
                    <div key={criterion._id} className="space-y-2">
                      <label className="block text-sm font-medium text-gray-700 flex items-center gap-2">
                        {criterion.name === "Critère scolaire" && <School className="h-4 w-4" />}
                        {criterion.name === "Critère familial" && <Users className="h-4 w-4" />}
                        {criterion.name === "Critère social" && <Heart className="h-4 w-4" />}
                        {criterion.name === "Critère physique" && <Activity className="h-4 w-4" />}
                        {criterion.name}
                      </label>
                      <select
                        value={
                          formData.criteria.find((c) => c.criterionId === criterion._id)?.description || ""
                        }
                        onChange={(e) => handleCriterionChange(criterion._id, e.target.value)}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      >
                        <option value="">Sélectionnez un critère</option>
                        {criterion.cases.map((caseItem, caseIndex) => (
                          <option key={caseIndex} value={caseItem.description}>
                            {caseItem.description} (Points: {caseItem.points})
                          </option>
                        ))}
                      </select>
                    </div>
                  ))}
                </div>
                <br />
                <div className="space-y-2">
                  <label className="block text-sm font-medium text-gray-700 flex items-center gap-2">
                    <Map className="h-4 w-4" />
                    En fonction de la ville d'origine du candidat, indiquez le nombre de points pour le critère géographique.
                  </label>
                  <input
                    type="number"
                    name="geographic_criteria"
                    value={formData.geographic_criteria}
                    onChange={handleChange}
                    className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                    required
                  />
                </div>
              </div>

              <div>
                <h3 className="text-lg font-medium text-gray-900 border-b pb-2">Notes supplémentaires</h3>
                <div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Observation</label>
                    <input
                      name="Observation"
                      value={formData.Observation}
                      onChange={handleChange}
                      className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Note (Calculée automatiquement)</label>
                    <input
                      name="Note"
                      value={formData.Note}
                      readOnly
                      className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm bg-gray-100"
                    />
                  </div>
                </div>
              </div>
            </div>

            <div className="mt-8 flex justify-end">
              <button
                type="button"
                onClick={() => navigate("/Candidates")}
                className="px-5 py-3 border border-gray-300 text-gray-700 rounded-md shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary mr-3"
              >
                Annuler
              </button>
              <button
                type="submit"
                disabled={isSubmitting}
                className="px-5 py-3 bg-primary text-primary-foreground rounded-md shadow-sm hover:bg-primary/90 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary flex items-center"
              >
                {isSubmitting ? (
                  <>
                    <svg
                      className="animate-spin -ml-1 mr-2 h-4 w-4 text-white"
                      xmlns="http://www.w3.org/2000/svg"
                      fill="none"
                      viewBox="0 0 24 24"
                    >
                      <circle
                        className="opacity-25"
                        cx="12"
                        cy="12"
                        r="10"
                        stroke="currentColor"
                        strokeWidth="4"
                      ></circle>
                      <path
                        className="opacity-75"
                        fill="currentColor"
                        d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                      ></path>
                    </svg>
                    Traitement...
                  </>
                ) : (
                  "Mettre à jour le candidat"
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </Layout>
  );
}
